  uz:{activation:'{mode}; {effect}.',autoActivation:'Sovgʻa qurilma avtomatik faollashadi',manualActivation:'Sovgʻa qurilmani qoʻlda faollashtirish kerak',effectiveIssued:'imtiyozlar berilganda kuchga kiradi',effectiveActivated:'imtiyozlar faollashtirilganda kuchga kiradi',noExpiry:'Bu sovgʻa qurilma uchun avtomatik tugash sanasi belgilanmagan.',duration:'Imtiyozlar {n} kun amal qiladi.',taskEnabled:'Bu qurilma hisoblash ishlarini bajara oladi.',taskDisabled:'Bu qurilma hisoblash ishlarini bajara olmaydi.',counting:'Qurilmalar soni: {holding}; daraja shartlari: {rank}.',holdingCounts:'hisoblanadi',holdingNotCounted:'hisoblanmaydi',rankCounts:'hisoblanadi',rankNotCounted:'hisoblanmaydi',transfer:'{transfer}; {exchange}.',transferable:'Oʻtkazish mumkin',notTransferable:'Oʻtkazib boʻlmaydi',exchangeable:'almashtirish mumkin',notExchangeable:'almashtirib boʻlmaydi',revokeUnused:'Sovgʻa qurilma ishlatilmaguncha qaytarib olinishi mumkin.',reviewUsed:'Ishlatilgan sovgʻa qurilma qoʻlda tekshiriladi.'},
};
const rights=computed(()=>{
  const d=props.disclosure.deviceRights;if(!d)return[];
  const c=rightsCopy[uiLocale(locale.code)];
  return[
    fmt(c.activation,{mode:d.activationMode==='AUTO'?c.autoActivation:c.manualActivation,effect:d.effectiveOn==='ISSUED'?c.effectiveIssued:c.effectiveActivated}),
